///       AF_FLUX_QUADRATIC
///     </td>
///     <td align="center">
///       \begin{equation}
///         \frac{1}{1 + (\frac{\| \nabla I\|}{K})^2}
///       \end{equation}
///     </td>
/// </tr>
/// <tr>
///     <td align="center" style="vertical-align:middle;">
///       AF_FLUX_EXPONENTIAL
///     </td>
///     <td align="center">
///       \begin{equation}
...
///    2001 pp. 142-145, Vol.3.
pub fn anisotropic_diffusion<T>(img: &Array<T>,
                                dt: f32, k: f32, iters: u32,
                                fftype: FluxFn,
